    fn claimRunAndFinishHostedForeignKeyActionJobGroupLocal(
        self: *HostedProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        db: *db_mod.DB,
        job_id: []const u8,
        action: []const u8,
        worker_id: []const u8,
        constraint_name: []const u8,
        parent_table: []const u8,
        parent_key: []const u8,
        updated_parent_key: ?[]const u8,
        page_limit: usize,
        lease_ms: u64,
        cascade_depth: u32,
        cascade_max_depth: u32,
    ) !db_mod.DB.ForeignKeyActionJobRecord {
        if (db.core.schema != null and try foreignKeyActionCanRunGroupDbLocal(
            alloc,
            self.catalog,
            group_id,
            table_name,
            constraint_name,
            parent_table,
            parent_key,
        )) {
            return try db.claimAndRunForeignKeyActionJobPageWithUpdatedParentKeyAndCascadeLineageAt(
                job_id,
                action,
                worker_id,
                constraint_name,
                parent_table,
                parent_key,
                updated_parent_key,
                page_limit,
                lease_ms,
                cascade_depth,
                cascade_max_depth,
                nextTxnTimestamp(),
            );
        }

        const claimed = try db.claimForeignKeyActionJobPageWithUpdatedParentKeyAndCascadeLineageAt(
            job_id,
            action,
            worker_id,
            constraint_name,
            parent_table,
            parent_key,
            updated_parent_key,
            page_limit,
            lease_ms,
            cascade_depth,
            cascade_max_depth,
            nextTxnTimestamp(),
        );
        var claimed_owned = true;
        defer if (claimed_owned) db.freeForeignKeyActionJobRecord(claimed);
        if (claimed.completed) {
            claimed_owned = false;
            return claimed;
        }

        var worker = distributed_txn.HostedParticipantWorker.init(self.catalog, self.router, self.source(), self.executor);
        const begin_timestamp = nextTxnTimestamp();
        var execution = distributed_txn.executeForeignKeyActionPage(
            alloc,
            self.catalog,
            worker.worker(),
            stableForeignKeyActionPageTxnId(claimed),
            begin_timestamp,
            begin_timestamp +| 1,
            table_name,
            group_id,
            action,
            constraint_name,
            parent_table,
            parent_key,
            claimed.updated_parent_key,
            claimed.next_child_table,
            claimed.next_child_key,
            page_limit,
            claimed.cascade_depth,
            claimed.cascade_max_depth,
            null,
        ) catch |err| {
            const failed = db.finishClaimedForeignKeyActionJobPage(
                claimed,
                0,
                false,
                claimed.next_child_table,
                claimed.next_child_key,
                @errorName(err),
            ) catch null;
            if (failed) |record| db.freeForeignKeyActionJobRecord(record);
            return err;
        };
        defer execution.deinit(alloc);

        return try db.finishClaimedForeignKeyActionJobPage(
            claimed,
            execution.applied_children,
            execution.complete,
            execution.next_child_table,
            execution.next_child_key,
            null,
        );
    }

    fn runHostedForeignKeyIntegrityWorkerPass(
        self: *HostedProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        action: ForeignKeyIntegrityAction,
        job_id: ?[]const u8,
        worker_id: []const u8,
        lease_ms: u64,
        max_work_units: usize,
        constraint_name: ?[]const u8,
        lower_doc_key: []const u8,
        upper_doc_key: []const u8,
        violation_limit: usize,
    ) !?ForeignKeyIntegrityResult {
        if (job_id) |id| {
            if (id.len == 0) return error.InvalidForeignKeyIntegrityRequest;
        }
        if (!foreignKeyIntegrityWorkerActionSupported(action)) return error.InvalidForeignKeyIntegrityRequest;
        if (worker_id.len == 0 or lease_ms == 0) return error.InvalidForeignKeyIntegrityRequest;

        const planned_units = try planForeignKeyIntegrityWorkerWorkUnits(alloc, self.catalog, table_name, action, constraint_name, lower_doc_key, upper_doc_key);
        defer {
            for (planned_units) |*unit| unit.deinit(alloc);
            if (planned_units.len > 0) alloc.free(planned_units);
        }
        if (planned_units.len == 0) return null;

        var initial_progress = std.ArrayListUnmanaged(ForeignKeyIntegrityProgress).empty;
        var initial_claims = std.ArrayListUnmanaged(ForeignKeyIntegrityWorkClaim).empty;
        defer {
            for (initial_progress.items) |*progress| progress.deinit(alloc);
            initial_progress.deinit(alloc);
            for (initial_claims.items) |*claim| claim.deinit(alloc);
            initial_claims.deinit(alloc);
        }
        try collectHostedForeignKeyIntegrityStatusSnapshot(self, alloc, table_name, planned_units, &initial_progress, &initial_claims);
        const initial_statuses = try buildForeignKeyIntegrityWorkStatuses(alloc, planned_units, initial_progress.items, initial_claims.items, .pending);
        defer {
            for (initial_statuses) |*status| status.deinit(alloc);
            if (initial_statuses.len > 0) alloc.free(initial_statuses);
        }

        var aggregate: db_mod.relational_store.ForeignKeyIntegrityReport = .{};
        var group_reports = std.ArrayListUnmanaged(ForeignKeyIntegrityGroupReport).empty;
        var violations = std.ArrayListUnmanaged(ForeignKeyIntegrityViolation).empty;
        errdefer {
            group_reports.deinit(alloc);
            for (violations.items) |*violation| violation.deinit(alloc);
            violations.deinit(alloc);
        }
        var truncated = false;
        var executed: usize = 0;
        const now_ns = foreignKeyIntegrityNowNs();
        for (planned_units, initial_statuses) |unit, status| {
            if (executed >= max_work_units) break;
            if (!foreignKeyIntegrityWorkStatusClaimable(status, now_ns)) continue;
            var one = (runHostedForeignKeyIntegrityClaimedWorkUnitRouted(
                self,
                alloc,
                table_name,
                unit,
                action,
                job_id,
                status.claim_key,
                worker_id,
                lease_ms,
                max_work_units,
                violation_limit -| violations.items.len,
            ) catch |err| switch (err) {
                error.ForeignKeyIntegrityClaimBusy => continue,
                else => return err,
            });
            defer one.deinit(alloc);
            try appendForeignKeyIntegrityExecutedResult(alloc, one, violation_limit, &aggregate, &group_reports, &violations, &truncated);
            executed += 1;
        }

        var final_progress = std.ArrayListUnmanaged(ForeignKeyIntegrityProgress).empty;
        var final_claims = std.ArrayListUnmanaged(ForeignKeyIntegrityWorkClaim).empty;
        errdefer {
            for (final_progress.items) |*progress| progress.deinit(alloc);
            final_progress.deinit(alloc);
            for (final_claims.items) |*claim| claim.deinit(alloc);
            final_claims.deinit(alloc);
        }
        try collectHostedForeignKeyIntegrityStatusSnapshot(self, alloc, table_name, planned_units, &final_progress, &final_claims);
        const work_statuses = try buildForeignKeyIntegrityWorkStatuses(alloc, planned_units, final_progress.items, final_claims.items, .pending);
        errdefer {
            for (work_statuses) |*status| status.deinit(alloc);
            if (work_statuses.len > 0) alloc.free(work_statuses);
        }
        const work_units = try cloneForeignKeyIntegrityWorkUnits(alloc, planned_units);
        errdefer {
            for (work_units) |*unit| unit.deinit(alloc);
            if (work_units.len > 0) alloc.free(work_units);
        }

        var result: ForeignKeyIntegrityResult = .{
            .action = action,
            .valid = foreignKeyIntegrityWorkStatusesValid(work_statuses),
            .complete = !foreignKeyIntegrityWorkStatusesHaveClaimable(work_statuses, foreignKeyIntegrityNowNs()),
            .violation_limit = violation_limit,
            .violations_truncated = truncated,
            .report = aggregate,
            .groups = try group_reports.toOwnedSlice(alloc),
            .progress = try final_progress.toOwnedSlice(alloc),
            .work_units = work_units,
            .work_claims = try final_claims.toOwnedSlice(alloc),
            .work_statuses = work_statuses,
            .violations = try violations.toOwnedSlice(alloc),
        };
        errdefer result.deinit(alloc);
        try attachForeignKeyIntegrityJobId(alloc, &result, job_id);
        return result;
    }

    fn runHostedForeignKeyIntegrityGroupLocal(
        self: *HostedProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        action: ForeignKeyIntegrityAction,
        constraint_name: ?[]const u8,
        lower_doc_key: []const u8,
        upper_doc_key: []const u8,
        violation_limit: usize,
    ) !?ForeignKeyIntegrityResult {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const mode: ManagedDbOpenMode = switch (action) {
            .plan, .validate, .dry_run, .list, .explain_delete, .progress => .status_only,
            .repair => .default,
        };
        const hosted_cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
        var cached = try self.getOrOpenCachedDbMode(hosted_cache, path, group_id, table_name, mode);
        defer cached.deinit(hosted_cache.write_cache.alloc);
        var result = try runForeignKeyIntegrityOnDb(alloc, cached.db, group_id, action, constraint_name, lower_doc_key, upper_doc_key, violation_limit);
        errdefer result.deinit(alloc);
        if (action == .repair) try drainManagedDbBeforeClose(cached.db);
        return result;
    }

    fn runHostedForeignKeyIntegrityClaimedWorkUnitGroupLocal(
        self: *HostedProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        action: ForeignKeyIntegrityAction,
        phase: []const u8,
        job_id: ?[]const u8,
        claim_key: []const u8,
        worker_id: []const u8,
        lease_ms: u64,
        max_work_units: usize,
        constraint_name: ?[]const u8,
        lower_doc_key: []const u8,
        upper_doc_key: []const u8,
        violation_limit: usize,
    ) !?ForeignKeyIntegrityResult {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const hosted_cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
        var cached = try self.getOrOpenCachedDbMode(hosted_cache, path, group_id, table_name, .default);
        defer cached.deinit(hosted_cache.write_cache.alloc);
        try startForeignKeyIntegrityJobOnDb(cached.db, job_id, table_name, action, worker_id, constraint_name, lower_doc_key, upper_doc_key, lease_ms, max_work_units);
        var result = try runForeignKeyIntegrityClaimedWorkUnitOnDb(
            alloc,
            cached.db,
            group_id,
            action,
            phase,
            claim_key,
            worker_id,
            lease_ms,
            constraint_name,
            lower_doc_key,
            upper_doc_key,
            violation_limit,
        );
        errdefer result.deinit(alloc);
        try finishForeignKeyIntegrityJobOnDb(alloc, cached.db, job_id, result);
        try attachForeignKeyIntegrityJobId(alloc, &result, job_id);
        try hydrateForeignKeyIntegrityResultDiagnosticsFromJobOnDb(alloc, cached.db, group_id, &result);
        try drainManagedDbBeforeClose(cached.db);
        return result;
    }

    fn runHostedUniqueConstraintIntegrityGroupLocal(
        self: *HostedProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        action: UniqueConstraintIntegrityAction,
        lower_doc_key: []const u8,
        upper_doc_key: []const u8,
    ) !?UniqueConstraintIntegrityResult {
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const mode: ManagedDbOpenMode = switch (action) {
            .progress => .status_only,
            .validate, .dry_run, .repair => .default,
        };
        const hosted_cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
        var cached = try self.getOrOpenCachedDbMode(hosted_cache, path, group_id, table_name, mode);
        defer cached.deinit(hosted_cache.write_cache.alloc);
        var result = try runUniqueConstraintIntegrityOnDb(alloc, cached.db, group_id, action, lower_doc_key, upper_doc_key);
        errdefer result.deinit(alloc);
        if (action == .validate or action == .dry_run or action == .repair) try drainManagedDbBeforeClose(cached.db);
        return result;
    }

    fn runHostedSecondaryIndexRebuildGroupLocal(
        self: *HostedProvisionedTableWriteSource,
        alloc: std.mem.Allocator,
        group_id: u64,
        table_name: []const u8,
        record: metadata_table_manager.SecondaryIndexRebuildRangeRecord,
        worker_id: []const u8,
        lease_ms: u64,
    ) !?SecondaryIndexRebuildWorkerResult {
        if (record.group_id != group_id) return error.InvalidSecondaryIndexRebuildRequest;
        const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
        defer alloc.free(path);
        const hosted_cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
        var cached = try self.getOrOpenCachedDbMode(hosted_cache, path, group_id, table_name, .default);
        defer cached.deinit(hosted_cache.write_cache.alloc);
        const now_ms = platform_time.monotonicNs() / std.time.ns_per_ms;
        const result = try runSecondaryIndexRebuildRangeGroupLocal(cached.db, self.catalog, record, worker_id, now_ms, lease_ms);
        if (result.claimed) try drainManagedDbBeforeClose(cached.db);
        return result;
    }

    fn corruptEmbeddingArtifact(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        doc_key: []const u8,
        index_name: []const u8,
    ) !?void {
        const self: *HostedProvisionedTableWriteSource = @ptrCast(@alignCast(ptr));
        const group_ids = try table_catalog.resolveGroupsForSpanEventually(
            alloc,
            self.catalog,
            table_name,
            "",
            "",
            5 * std.time.ns_per_s,
            10,
        );
        defer alloc.free(group_ids);
        if (group_ids.len == 0) return null;

        for (group_ids) |group_id| {
            const path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, self.replica_root_dir, group_id);
            defer alloc.free(path);
            const hosted_cache = try hostedManagedDbCacheForRoot(self.replica_root_dir);
            var cached = try self.getOrOpenCachedDbMode(hosted_cache, path, group_id, table_name, .default);
            defer cached.deinit(hosted_cache.write_cache.alloc);
            if (try corruptEmbeddingArtifactInDb(alloc, cached.db, doc_key, index_name)) return;
        }

        return error.NotFound;
    }
};

const GroupBatch = struct {
    group_id: u64,
    writes: std.ArrayListUnmanaged(db_mod.types.BatchWrite) = .empty,
    deletes: std.ArrayListUnmanaged([]const u8) = .empty,
    relational_identity_rewrites: std.ArrayListUnmanaged(db_mod.types.RelationalIdentityRewrite) = .empty,
    transforms: std.ArrayListUnmanaged(db_mod.types.DocumentTransform) = .empty,

    fn deinit(self: *GroupBatch, alloc: std.mem.Allocator) void {
        self.writes.deinit(alloc);
        self.deletes.deinit(alloc);
        self.relational_identity_rewrites.deinit(alloc);
        self.transforms.deinit(alloc);
        self.* = undefined;
    }
};

fn cloneWriteCoalesceGroupBatch(
    alloc: std.mem.Allocator,
    group: GroupBatch,
) !GroupBatch {
    var cloned = GroupBatch{ .group_id = group.group_id };
    errdefer freeWriteCoalesceGroupBatch(alloc, &cloned);

    try cloned.writes.ensureTotalCapacity(alloc, group.writes.items.len);
    for (group.writes.items) |write| {
        const key = try alloc.dupe(u8, write.key);
        const value = alloc.dupe(u8, write.value) catch |err| {
            alloc.free(key);
            return err;
        };
        cloned.writes.appendAssumeCapacity(.{ .key = key, .value = value });
    }

    try cloned.deletes.ensureTotalCapacity(alloc, group.deletes.items.len);
    for (group.deletes.items) |key| {
        const owned_key = try alloc.dupe(u8, key);
        cloned.deletes.appendAssumeCapacity(owned_key);
    }

    try cloned.relational_identity_rewrites.ensureTotalCapacity(alloc, group.relational_identity_rewrites.items.len);
    for (group.relational_identity_rewrites.items) |rewrite| {
        const old_key = try alloc.dupe(u8, rewrite.old_key);
        var old_key_owned = true;
        errdefer if (old_key_owned) alloc.free(old_key);
        const new_key = try alloc.dupe(u8, rewrite.new_key);
        var new_key_owned = true;
        errdefer if (new_key_owned) alloc.free(new_key);
        const value = try alloc.dupe(u8, rewrite.value);
        var value_owned = true;
        errdefer if (value_owned) alloc.free(value);
        cloned.relational_identity_rewrites.appendAssumeCapacity(.{
            .old_key = old_key,
            .new_key = new_key,
            .value = value,
        });
        old_key_owned = false;
        new_key_owned = false;
        value_owned = false;
    }

    return cloned;
}

fn freeWriteCoalesceGroupBatch(alloc: std.mem.Allocator, group: *GroupBatch) void {
    for (group.writes.items) |write| {
        alloc.free(write.key);
        alloc.free(write.value);
    }
    for (group.deletes.items) |key| alloc.free(key);
    for (group.relational_identity_rewrites.items) |rewrite| {
        alloc.free(@constCast(rewrite.old_key));
        alloc.free(@constCast(rewrite.new_key));
        alloc.free(@constCast(rewrite.value));
    }
    group.deinit(alloc);
}

fn ensureGroupBatch(
    alloc: std.mem.Allocator,
    grouped: *std.ArrayListUnmanaged(GroupBatch),
    group_id: u64,
) !*GroupBatch {
    for (grouped.items) |*group| {
        if (group.group_id == group_id) return group;
    }
    try grouped.append(alloc, .{ .group_id = group_id });
    return &grouped.items[grouped.items.len - 1];
}

fn applyGroupBatch(
    alloc: std.mem.Allocator,
    catalog: table_catalog.CatalogSource,
    db: *db_mod.DB,
    table_name: []const u8,
    group: GroupBatch,
    req: db_mod.types.BatchRequest,
) !void {
    try validateTableBatchAgainstCatalogSchema(alloc, catalog, db, table_name, group.writes.items, group.deletes.items, group.transforms.items);
    try applyGroupBatchUnchecked(db, group, req);
}

fn applyGroupBatchWithSchemaJson(
    alloc: std.mem.Allocator,
    db: *db_mod.DB,
    schema_json: ?[]const u8,
    group: GroupBatch,
    req: db_mod.types.BatchRequest,
) !void {
    try validateTableBatchAgainstSchemaJson(alloc, db, schema_json, group.writes.items, group.deletes.items, group.transforms.items);
    try applyGroupBatchUnchecked(db, group, req);
}

fn applyGroupBatchUnchecked(
    db: *db_mod.DB,
    group: GroupBatch,
    req: db_mod.types.BatchRequest,
) !void {
    runTestBeforeBatchExecutionHook();
    try db.batch(.{
        .writes = group.writes.items,
        .deletes = group.deletes.items,
        .relational_identity_rewrites = group.relational_identity_rewrites.items,
        .transforms = group.transforms.items,
        .graph_writes = req.graph_writes,
        .graph_deletes = req.graph_deletes,
        .predicates = req.predicates,
        .timestamp_ns = req.timestamp_ns,
        .sync_level = req.sync_level,
    });
    if (shouldDrainManagedDbAfterBatch(req.sync_level)) try drainManagedDbBeforeClose(db);
}

fn parseIndexKind(value: std.json.Value) !db_mod.types.IndexKind {
    if (value != .object) return .full_text;
    const type_value = value.object.get("type") orelse return .full_text;
    if (type_value != .string) return error.InvalidCreateTableRequest;
    if (std.mem.eql(u8, type_value.string, "full_text")) return .full_text;
    if (std.mem.eql(u8, type_value.string, "graph")) return .graph;
    if (std.mem.eql(u8, type_value.string, "algebraic")) return .algebraic;
    if (std.mem.eql(u8, type_value.string, "embeddings")) {
        const sparse = if (value.object.get("sparse")) |sparse_value| switch (sparse_value) {
            .bool => sparse_value.bool,
            else => return error.InvalidCreateTableRequest,
        } else false;
        return if (sparse) .sparse_vector else .dense_vector;
    }
    return error.UnsupportedCreateTableRequest;
}

fn parseIndexConfig(alloc: std.mem.Allocator, index_name: []const u8, index_json: []const u8) !db_mod.types.IndexConfig {
    return try parseIndexConfigWithOptions(alloc, index_name, index_json, .{});
}

fn parseIndexConfigWithOptions(
    alloc: std.mem.Allocator,
    index_name: []const u8,
    index_json: []const u8,
    options: managed_embedder.InitOptions,
) !db_mod.types.IndexConfig {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, index_json, .{});
    defer parsed.deinit();
    const kind = try parseIndexKind(parsed.value);
    const config_json = try extractIndexConfigJsonWithOptions(alloc, index_name, parsed.value, options);
    errdefer alloc.free(config_json);
    return .{
        .name = try alloc.dupe(u8, index_name),
        .kind = kind,
        .config_json = config_json,
    };
}

pub fn validateIndexConfig(alloc: std.mem.Allocator, index_name: []const u8, index_json: []const u8) !void {
    return try validateIndexConfigWithOptions(alloc, index_name, index_json, .{});
}

pub fn validateIndexConfigWithOptions(
    alloc: std.mem.Allocator,
    index_name: []const u8,
    index_json: []const u8,
    options: managed_embedder.InitOptions,
) !void {
    const cfg = try parseIndexConfigWithOptions(alloc, index_name, index_json, options);
    defer {
        alloc.free(cfg.name);
        alloc.free(cfg.config_json);
    }
    if (cfg.kind == .algebraic) {
        var parsed = std.json.parseFromSlice(db_mod.algebraic.index.Config, alloc, cfg.config_json, .{
            .allocate = .alloc_always,
            .ignore_unknown_fields = true,
        }) catch return error.InvalidCreateTableRequest;
        defer parsed.deinit();
        db_mod.algebraic.index.validateConfig(parsed.value) catch return error.InvalidCreateTableRequest;
    }
}

fn extractIndexConfigJson(alloc: std.mem.Allocator, index_name: []const u8, value: std.json.Value) ![]u8 {
    return try extractIndexConfigJsonWithOptions(alloc, index_name, value, .{});
}

fn extractIndexConfigJsonWithOptions(
    alloc: std.mem.Allocator,
    index_name: []const u8,
    value: std.json.Value,
    options: managed_embedder.InitOptions,
) ![]u8 {
    if (value != .object) return try alloc.dupe(u8, "{}");
    const kind = try parseIndexKind(value);
    switch (kind) {
        .dense_vector, .sparse_vector => return try managed_embedder.translateEmbeddingsIndexConfigJsonWithOptions(alloc, index_name, value, options),
        else => {},
    }

    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;
    var it = value.object.iterator();
    while (it.next()) |entry| {
        if (std.mem.eql(u8, entry.key_ptr.*, "type") or
            std.mem.eql(u8, entry.key_ptr.*, "name") or
            std.mem.eql(u8, entry.key_ptr.*, "description") or
            std.mem.eql(u8, entry.key_ptr.*, "validation") or
            std.mem.eql(u8, entry.key_ptr.*, "enrichments"))
        {
            continue;
        }
        if (std.mem.eql(u8, entry.key_ptr.*, "version") and kind != .algebraic) continue;
        if (!first) try out.append(alloc, ',');
        first = false;
        try appendJsonString(alloc, &out, entry.key_ptr.*);
        try out.append(alloc, ':');
        const encoded = try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(entry.value_ptr.*, .{})});
        defer alloc.free(encoded);
        try out.appendSlice(alloc, encoded);
    }
    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

pub fn normalizeManagedEmbeddingIndexDimensionJsonWithOptions(
    alloc: std.mem.Allocator,
    index_name: []const u8,
    index_json: []const u8,
    options: managed_embedder.InitOptions,
) ![]u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, index_json, .{});
    defer parsed.deinit();
    if (try managed_embedder.normalizeEmbeddingsIndexDimensionJsonWithOptions(alloc, index_name, parsed.value, options)) |normalized| {
        return normalized;
    }
    return try alloc.dupe(u8, index_json);
}

pub fn normalizeManagedEmbeddingIndexDimensionsJsonWithOptions(
    alloc: std.mem.Allocator,
    indexes_json: []const u8,
    options: managed_embedder.InitOptions,
) ![]u8 {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, indexes_json, .{});
    defer parsed.deinit();
    const object = switch (parsed.value) {
        .object => |object| object,
        else => return error.InvalidCreateTableRequest,
    };

    var out = std.ArrayListUnmanaged(u8).empty;
    defer out.deinit(alloc);
    try out.append(alloc, '{');
    var first = true;
    var it = object.iterator();
    while (it.next()) |entry| {
        if (!first) try out.append(alloc, ',');
        first = false;
        try appendJsonString(alloc, &out, entry.key_ptr.*);
        try out.append(alloc, ':');
        if (try managed_embedder.normalizeEmbeddingsIndexDimensionJsonWithOptions(alloc, entry.key_ptr.*, entry.value_ptr.*, options)) |normalized| {
            defer alloc.free(normalized);
            try out.appendSlice(alloc, normalized);
        } else {
            const encoded = try std.fmt.allocPrint(alloc, "{f}", .{std.json.fmt(entry.value_ptr.*, .{})});
            defer alloc.free(encoded);
            try out.appendSlice(alloc, encoded);
        }
    }
    try out.append(alloc, '}');
    return try out.toOwnedSlice(alloc);
}

test "table write index parser extracts expanded algebraic capability config" {
    const alloc = std.testing.allocator;
    const cfg = try parseIndexConfig(alloc, "sales_rollup",
        \\{"type":"algebraic","version":1,"table":"sales","group_fields":[{"name":"customer","path":"customer","type":"keyword"}],"measure_fields":[{"name":"amount","path":"amount","type":"number"}],"materializations":[]}
    );
    defer {
        alloc.free(cfg.name);
        alloc.free(cfg.config_json);
    }

    try std.testing.expectEqual(db_mod.types.IndexKind.algebraic, cfg.kind);
    try std.testing.expectEqualStrings("sales_rollup", cfg.name);
    try std.testing.expect(std.mem.indexOf(u8, cfg.config_json, "\"version\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, cfg.config_json, "\"group_fields\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, cfg.config_json, "\"measure_fields\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, cfg.config_json, "\"materializations\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, cfg.config_json, "\"type\":\"algebraic\"") == null);
}

