    var cached = try apply_source.getOrOpenCachedDbMode(alloc, &apply_cache, path, 7001, "docs", .default_async, null, null);
    cached.deinit(alloc);
    try std.testing.expectEqual(misses_before, apply_cache.miss_count.load(.monotonic));
}

